import threading
import queue
from typing import Callable


class QueueWorker:
    def __init__(self, callback: Callable, num_workers: int = 1):
        self.callback = callback
        self.queue = queue.Queue()
        self.num_workers = num_workers
        self.threads = []
        self.running = False

    def start(self):
        """Start worker threads."""
        self.running = True
        for _ in range(self.num_workers):
            t = threading.Thread(target=self._worker_loop, daemon=False)
            t.start()
            self.threads.append(t)

    def _worker_loop(self):
        """Process items from queue until stopped."""
        while self.running:
            try:
                item = self.queue.get(timeout=1)
                if item is None:
                    self.queue.task_done()
                    break
                self.callback(item)
                self.queue.task_done()
            except queue.Empty:
                continue

    def put(self, item):
        """Add item to queue."""
        self.queue.put(item)

    def stop(self):
        """Stop all workers gracefully."""
        self.running = False
        for _ in range(self.num_workers):
            self.queue.put(None)
        for t in self.threads:
            t.join()

    def wait(self):
        """Block until queue is empty."""
        self.queue.join()


if __name__ == "__main__":
    def process(item):
        print(f"Processing: {item}")

    worker = QueueWorker(callback=process, num_workers=2)
    worker.start()
    for i in range(5):
        worker.put(i)
    worker.wait()
    worker.stop()
